-- Read-only catalog fingerprint; run against verified disposable LOCAL database only.
-- Production counterpart executed via authorized connector, 2026-11-26.
WITH objects AS (
SELECT 'relations' AS kind, c.relname AS object_key, jsonb_build_array(c.relkind,c.relrowsecurity,c.relforcerowsecurity,pg_get_userbyid(c.relowner),c.reloptions)::text AS definition FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','S')
UNION ALL SELECT 'columns',c.relname||'.'||a.attname,jsonb_build_array(a.attnum,format_type(a.atttypid,a.atttypmod),a.attnotnull,a.attidentity,a.attgenerated,pg_get_expr(d.adbin,d.adrelid),CASE WHEN a.attcollation<>0 THEN a.attcollation::regcollation::text END)::text FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m') AND a.attnum>0 AND NOT a.attisdropped
UNION ALL SELECT 'constraints',c.relname||'.'||k.conname,jsonb_build_array(k.contype,pg_get_constraintdef(k.oid,false),k.convalidated,k.condeferrable,k.condeferred)::text FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'
UNION ALL SELECT 'indexes',i.relname,jsonb_build_array(pg_get_indexdef(i.oid),x.indisvalid,x.indisready,x.indisunique,x.indisprimary)::text FROM pg_index x JOIN pg_class i ON i.oid=x.indexrelid JOIN pg_class c ON c.oid=x.indrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'
UNION ALL SELECT 'policies',c.relname||'.'||p.polname,jsonb_build_array(p.polcmd,p.polpermissive,ARRAY(SELECT CASE WHEN role_oid=0 THEN 'PUBLIC' ELSE pg_get_userbyid(role_oid) END FROM unnest(p.polroles) AS role_oid ORDER BY 1),pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid))::text FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'
UNION ALL SELECT 'functions',p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',jsonb_build_array(pg_get_functiondef(p.oid),pg_get_userbyid(p.proowner),p.prosecdef,p.proconfig)::text FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind IN ('f','p','w')
UNION ALL SELECT 'triggers',c.relname||'.'||t.tgname,jsonb_build_array(pg_get_triggerdef(t.oid,false),t.tgenabled)::text FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal
UNION ALL SELECT 'views',c.relname,pg_get_viewdef(c.oid,false) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('v','m')
UNION ALL SELECT 'relation_grants',c.relname,jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable)::text FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(COALESCE(c.relacl,acldefault(CASE WHEN c.relkind='S' THEN 's'::"char" ELSE 'r'::"char" END,c.relowner))) a WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','S')
UNION ALL SELECT 'function_grants',p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',jsonb_build_array(pg_get_userbyid(a.grantor),CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable)::text FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname='public' AND p.prokind IN ('f','p','w')
UNION ALL SELECT 'extensions',e.extname,jsonb_build_array(e.extversion,n.nspname)::text FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace
UNION ALL SELECT 'migrations',version,version FROM supabase_migrations.schema_migrations
) SELECT kind,count(*) AS object_count,md5(string_agg(jsonb_build_array(object_key,definition)::text,E'\n' ORDER BY object_key COLLATE "C",definition COLLATE "C")) AS fingerprint FROM objects GROUP BY kind ORDER BY kind;
